 30: /* ── Tema warna FAST ──────────────────────────────────────────────── */
 31: :root {
 32:   --theme-primary: #0a192f;
 33:   --theme-secondary: #112240;
 34:   --theme-accent: #3898d4;
 35: 
 36:   --theme-background: #000000;
 37:   --theme-surface: #0b1120;
 38: 
 39:   --theme-foreground: #ffffff;
 40:   --theme-foreground-muted: #94a3b8;
 41: 
 42:   --theme-border: #1e293b;
 43: 
 44:   --section-padding-y: 6rem;
 45:   --transition-base: all 0.3s ease-in-out;
 46: }
 47: 
 48: /* ── Base ─────────────────────────────────────────────────────────── */
 49: @layer base {
 50:   html {
 51:     scroll-behavior: smooth;
 52:     scroll-padding-top: 5rem;
 53:     text-rendering: optimizeLegibility;
 54:     -webkit-font-smoothing: antialiased;
 55:     -moz-osx-font-smoothing: grayscale;
 56:   }
 57: 
 58:   body {
 59:     background-color: var(--theme-background);
 60:     color: var(--theme-foreground);
 61:     font-family: var(--font-sans);
 62:     overflow-x: hidden;
 63:     /* Subpixel hint untuk font lebih tajam di dark bg */
 64:     font-synthesis: none;
 65:   }
 66: 
 67:   h1,
 68:   h2,
 69:   h3,
 70:   h4,
 71:   h5,
 72:   h6 {
 73:     font-family: var(--font-heading);
 74:     letter-spacing: 0.03em;
 75:   }
 76: 
 77:   /* ── Focus ring global ───────────────── */
 78:   *:focus-visible {
 79:     outline: 2px solid var(--theme-accent);
 80:     outline-offset: 3px;
 81:     border-radius: 6px;
 82:   }
 83: 
 84:   /* ── Text selection ──────────────────── */
 85:   ::selection {
 86:     background-color: color-mix(in srgb, var(--theme-accent) 35%, transparent);
 87:     color: #ffffff;
 88:   }
 89:   ::-moz-selection {
 90:     background-color: color-mix(in srgb, var(--theme-accent) 35%, transparent);
 91:     color: #ffffff;
 92:   }
 93: 
 94:   /* ── Custom scrollbar ────────────────── */
 95:   ::-webkit-scrollbar {
 96:     width: 8px;
 97:     height: 8px;
 98:   }
 99:   ::-webkit-scrollbar-track {
100:     background: var(--theme-background);
101:   }
102:   ::-webkit-scrollbar-thumb {
103:     background: #1e293b;
104:     border-radius: 999px;
105:     border: 2px solid var(--theme-background);
106:     transition: background 0.2s;
107:   }
108:   ::-webkit-scrollbar-thumb:hover {
109:     background: var(--theme-accent);
110:   }
111: 
112:   /* ── Skip link ───────────────────────── */
113:   .skip-link {
114:     position: absolute;
115:     left: -9999px;
116:     top: 0;
117:     z-index: 100;
118:     padding: 0.75rem 1.25rem;
119:     background-color: var(--theme-accent);
120:     color: #fff;
121:     font-weight: 600;
122:     text-decoration: none;
123:     border-radius: 0 0 0.5rem 0;
124:     transition: left 0.2s ease-in-out;
125:   }
126:   .skip-link:focus {
127:     left: 0;
128:     outline: none;
129:   }
130: }
131: 
132: /* ── Utilities ────────────────────────────────────────────────────── */
133: @layer utilities {
134:   .text-outline-white {
135:     -webkit-text-stroke: 1px rgba(255, 255, 255, 0.3);
136:     color: transparent;
137:   }
138:   /* Shine sweep — dipakai oleh Button, WhatsApp CTA, dll */
139:   .shine {
140:     position: relative;
141:     overflow: hidden;
142:   }
143:   .shine::before {
144:     content: "";
145:     position: absolute;
146:     inset: 0;
147:     transform: translateX(-100%);
148:     background: linear-gradient(
149:       90deg,
150:       transparent 0%,
151:       rgba(255, 255, 255, 0.12) 50%,
152:       transparent 100%
153:     );
154:     transition: transform 0.55s ease;
155:     pointer-events: none;
156:   }
157:   .shine:hover::before {
158:     transform: translateX(100%);
159:   }
160: 
161:   /* Glow text gradient — dipakai hero headline */
162:   .text-glow {
163:     text-shadow: 0 0 40px rgba(56, 152, 212, 0.4);
164:   }
165: 
166:   /* Glass card — consistent border+bg pattern */
167:   .glass {
168:     background: rgba(11, 17, 32, 0.5);
169:     backdrop-filter: blur(12px);
170:     border: 1px solid rgba(255, 255, 255, 0.06);
171:   }
172: 
173:   /* Subtle grid overlay — decorative bg pattern */
174:   .bg-grid {
175:     background-image:
176:       linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
177:       linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
178:     background-size: 64px 64px;
179:   }
180: 
181:   /* Noise texture overlay — optional depth on sections */
182:   .bg-noise {
183:     background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
184:     background-repeat: repeat;
185:     background-size: 200px 200px;
186:   }
187: 
188:   /* Animated gradient border — accent ring on interactive elements */
189:   .border-gradient {
190:     border: 1px solid transparent;
191:     background-clip: padding-box;
192:     position: relative;
193:   }
194:   .border-gradient::before {
195:     content: "";
196:     position: absolute;
197:     inset: -1px;
198:     border-radius: inherit;
199:     background: linear-gradient(
200:       135deg,
201:       rgba(56, 152, 212, 0.4),
202:       transparent 60%
203:     );
204:     z-index: -1;
205:     opacity: 0;
206:     transition: opacity 0.3s;
207:   }
208:   .border-gradient:hover::before {
209:     opacity: 1;
210:   }
211: }
212: 
213: /* ── Keyframe animations (CSS-only, zero JS) ─────────────────────── */
214: @keyframes float {
215:   0%,
216:   100% {
217:     transform: translateY(0px);
218:   }
219:   50% {
220:     transform: translateY(-8px);
221:   }
222: }
223: 
224: @keyframes float-slow {
225:   0%,
226:   100% {
227:     transform: translateY(0px) rotate(0deg);
228:   }
229:   33% {
230:     transform: translateY(-6px) rotate(1deg);
231:   }
232:   66% {
233:     transform: translateY(-3px) rotate(-1deg);
234:   }
235: }
236: 
237: @keyframes glow-pulse {
238:   0%,
239:   100% {
240:     opacity: 0.04;
241:     transform: scale(1);
242:   }
243:   50% {
244:     opacity: 0.08;
245:     transform: scale(1.08);
246:   }
247: }
248: 
249: @keyframes shimmer {
250:   0% {
251:     background-position: -200% center;
252:   }
253:   100% {
254:     background-position: 200% center;
255:   }
256: }
257: 
258: @keyframes fade-up {
259:   from {
260:     opacity: 0;
261:     transform: translateY(16px);
262:   }
263:   to {
264:     opacity: 1;
265:     transform: translateY(0);
266:   }
267: }
268: 
269: @keyframes spin-slow {
270:   from {
271:     transform: rotate(0deg);
272:   }
273:   to {
274:     transform: rotate(360deg);
275:   }
276: }
277: 
278: /* Utility classes untuk keyframes */
279: .animate-float {
280:   animation: float 4s ease-in-out infinite;
281: }
282: .animate-float-slow {
283:   animation: float-slow 6s ease-in-out infinite;
284: }
285: .animate-glow-pulse {
286:   animation: glow-pulse 6s ease-in-out infinite;
287: }
288: .animate-fade-up {
289:   animation: fade-up 0.5s ease-out both;
290: }
291: .animate-spin-slow {
292:   animation: spin-slow 12s linear infinite;
293: }
294: 
295: /* Shimmer loading skeleton */
296: .animate-shimmer {
297:   background: linear-gradient(
298:     90deg,
299:     rgba(255, 255, 255, 0.03) 0%,
300:     rgba(255, 255, 255, 0.08) 50%,
301:     rgba(255, 255, 255, 0.03) 100%
302:   );
303:   background-size: 200% auto;
304:   animation: shimmer 1.8s linear infinite;
305: }
306: 
307: /* ── Reduced motion ──────────────────────────────────────────────── */
308: @media (prefers-reduced-motion: reduce) {
309:   html {
310:     scroll-behavior: auto;
311:   }
312: 
313:   *,
314:   *::before,
315:   *::after {
316:     animation-duration: 0.01ms !important;
317:     animation-iteration-count: 1 !important;
318:     transition-duration: 0.01ms !important;
319:   }
320: 
321:   /* Matikan parallax glow di MainLayout */
322:   .will-change-transform {
323:     will-change: auto !important;
324:     transform: none !important;
325:   }
326: }

