 23: export const WhatsAppButton = () => {
 24:   const [visible, setVisible] = useState(false);
 25:   const [showTooltip, setShowTooltip] = useState(false);
 26: 
 27:   useEffect(() => {
 28:     const onScroll = () => setVisible(window.scrollY > 120);
 29:     window.addEventListener("scroll", onScroll, { passive: true });
 30:     const timer = setTimeout(() => setVisible(true), 3000);
 31:     return () => {
 32:       window.removeEventListener("scroll", onScroll);
 33:       clearTimeout(timer);
 34:     };
 35:   }, []);
 36: 
 37:   useEffect(() => {
 38:     if (!visible) return;
 39:     const t = setTimeout(() => {
 40:       setShowTooltip(true);
